DO $$
BEGIN
   UPDATE trial_accounts SET converted_revenue = 500 WHERE trial_start_date < CURRENT_DATE - INTERVAL '90 days' AND initial_seats >= 5;
   UPDATE trial_accounts SET converted_revenue = 750 WHERE converted_revenue IS NULL AND initial_seats >= 10;
   UPDATE trial_accounts SET converted_revenue = 250 WHERE converted_revenue IS NULL AND trial_start_date < CURRENT_DATE - INTERVAL '60 days';

END $$;

SELECT *
  FROM trial_accounts
 ORDER BY account_id;
